/** Repository of the "categories" table: reads and writes rows, and decides nothing. */
import { asc, count, eq } from 'drizzle-orm'
import { isRefusal, type Db } from '../database.js'
import { Category } from '../entities/category.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'
import { categories } from '../schema.js'

/** Where categories rows are kept. Services depend only on this interface. */
export interface CategoryRepository {
  findById(id: number): Promise<Category | null>
  list(offset?: number, limit?: number): Promise<Page<Category>>
  findByName(name: string): Promise<Category | null>
  insert(entity: Category): Promise<Category>
  update(entity: Category): Promise<Category>
  delete(entity: Category): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Category): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Category of a row Drizzle read. */
function toEntity(row: typeof categories.$inferSelect): Category {
  return Object.assign(new Category(), row)
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Category): typeof categories.$inferInsert {
  return {
    id: entity.id,
    name: entity.name,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Category): Partial<typeof categories.$inferInsert> {
  return {
    name: entity.name,
  }
}

/** Keeps categories rows in the database, through Drizzle. It never commits: the transaction belongs to the database it was given. */
export class SqlCategoryRepository implements CategoryRepository {
  constructor(private readonly db: Db) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Category | null> {
    const [row] = await this.db.select().from(categories).where(eq(categories.id, id)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Category>> {
    const rows = await this.db.select().from(categories).orderBy(asc(categories.id)).limit(limit).offset(offset)
    const [{ total }] = await this.db.select({ total: count() }).from(categories)
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** The row with this name, or null. */
  async findByName(name: string): Promise<Category | null> {
    const [row] = await this.db.select().from(categories).where(eq(categories.name, name)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Category): Promise<Category> {
    try {
      const [row] = await this.db.insert(categories).values(insertValues(entity)).returning()
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Category', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Category): Promise<Category> {
    try {
      await this.db.update(categories).set(updateValues(entity)).where(eq(categories.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Category', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Category): Promise<void> {
    try {
      await this.db.delete(categories).where(eq(categories.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Category', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }
}

/** Keeps categories rows in memory, for tests and for trying the services without a database. */
export class MemoryCategoryRepository implements CategoryRepository {
  private readonly rows = new Map<string, Category>()
  private nextId = 1

  private visible(): Category[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Category | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Category>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** The row with this name, or null. */
  async findByName(name: string): Promise<Category | null> {
    return this.visible().find((row) => row.name === name) ?? null
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Category): Promise<Category> {
    if (entity.id === undefined) entity.id = this.nextId++
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Category): Promise<Category> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Category): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

