/** Repository of the "tags" table: reads and writes rows, and decides nothing. */
import { asc, count, eq } from 'drizzle-orm'
import { isRefusal, type Db } from '../database.js'
import { Tag } from '../entities/tag.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'
import { tags } from '../schema.js'

/** Where tags rows are kept. Services depend only on this interface. */
export interface TagRepository {
  findById(id: number): Promise<Tag | null>
  list(offset?: number, limit?: number): Promise<Page<Tag>>
  insert(entity: Tag): Promise<Tag>
  update(entity: Tag): Promise<Tag>
  delete(entity: Tag): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Tag): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Tag of a row Drizzle read. */
function toEntity(row: typeof tags.$inferSelect): Tag {
  return Object.assign(new Tag(), row)
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Tag): typeof tags.$inferInsert {
  return {
    id: entity.id,
    label: entity.label,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Tag): Partial<typeof tags.$inferInsert> {
  return {
    label: entity.label,
  }
}

/** Keeps tags rows in the database, through Drizzle. It never commits: the transaction belongs to the database it was given. */
export class SqlTagRepository implements TagRepository {
  constructor(private readonly db: Db) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Tag | null> {
    const [row] = await this.db.select().from(tags).where(eq(tags.id, id)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Tag>> {
    const rows = await this.db.select().from(tags).orderBy(asc(tags.id)).limit(limit).offset(offset)
    const [{ total }] = await this.db.select({ total: count() }).from(tags)
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Tag): Promise<Tag> {
    try {
      const [row] = await this.db.insert(tags).values(insertValues(entity)).returning()
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Tag', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Tag): Promise<Tag> {
    try {
      await this.db.update(tags).set(updateValues(entity)).where(eq(tags.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Tag', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Tag): Promise<void> {
    try {
      await this.db.delete(tags).where(eq(tags.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Tag', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }
}

/** Keeps tags rows in memory, for tests and for trying the services without a database. */
export class MemoryTagRepository implements TagRepository {
  private readonly rows = new Map<string, Tag>()
  private nextId = 1

  private visible(): Tag[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Tag | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Tag>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Tag): Promise<Tag> {
    if (entity.id === undefined) entity.id = this.nextId++
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Tag): Promise<Tag> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Tag): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

